const has = (hero, skill) => hero.skills.includes(skill);
export const vitalityRecovery = hero => (has(hero, 'vit2') ? 1 : 0) + (has(hero, 'vit4') ? 3 : 0);
export const vitalityShield = hero => has(hero, 'vit3') ? 1 : 0;
export const vitalityHazardReduction = hero => has(hero, 'vit5') ? 2 : 0;
export const vitalityRescueRecovery = hero => has(hero, 'vit6') ? 6 : 0;
